using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckBowling;using LWS.TruckTerrierRacing;
namespace LWS.TruckSports {
public sealed class SportsCabSteeringProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsCabSteering")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.CabSteeringProbe",false);UnityEditor.SessionState.SetBool("LWS.CabSteeringProbe",false);
#endif
 if(run)new GameObject("Cab steering native validation").AddComponent<SportsCabSteeringProbe>();}
 IEnumerator Start(){var oldBackground=UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior;UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;var fixtureKeyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>();UnityEngine.InputSystem.InputSystem.EnableDevice(fixtureKeyboard);yield return null;var m=FindAnyObjectByType<TerrierMatch>();if(m==null)yield break;string saved=PlayerPrefs.GetString(m.PreferenceKey);bool had=PlayerPrefs.HasKey(m.PreferenceKey);var log=new StringBuilder();int errors=0;for(int i=0;i<12;i++)m.setup.players[i].source=i<4?BowlingSource.Keyboard:BowlingSource.AI;m.option=0;if(!m.StartMatch())throw new InvalidOperationException("Four-view steering fixture cannot start");m.enabled=false;float[] inputs={-1,-.33f,.5f,1};for(int i=0;i<4;i++){m.racers[i].Release();m.cabViews[i].cabSteering.Bind(m.racers[i].truck);m.racers[i].truck.TickDrive(new Vector2(inputs[i],0));}yield return new WaitForSecondsRealtime(2.5f);for(int i=0;i<4;i++){var c=m.cabViews[i].cabSteering;float expected=inputs[i]*450;bool ok=c.Truck==m.racers[i].truck&&Mathf.Abs(c.CurrentAngle-expected)<1;log.AppendLine((ok?"PASS ":"FAIL ")+"independent cab "+i+" actualNWH="+m.racers[i].truck.wheels[0].SteerAngle+" target="+c.TargetAngle+" visibleAngle="+c.CurrentAngle);if(!ok)errors++;}
 float before=m.cabViews[0].cabSteering.CurrentAngle;m.Pause();yield return new WaitForSecondsRealtime(.2f);bool frozen=m.cabViews[0].cabSteering.CurrentAngle==before;log.AppendLine((frozen?"PASS ":"FAIL ")+"paused steering presentation is frozen");if(!frozen)errors++;m.Resume();for(int i=0;i<4;i++)m.racers[i].truck.TickDrive(Vector2.zero);yield return new WaitForSecondsRealtime(1.5f);for(int i=0;i<4;i++){bool centered=Mathf.Abs(m.cabViews[i].cabSteering.CurrentAngle)<1;log.AppendLine((centered?"PASS ":"FAIL ")+"cab returns smoothly to center "+i);if(!centered)errors++;}m.enabled=true;m.SetupScreen();if(had)PlayerPrefs.SetString(m.PreferenceKey,saved);else PlayerPrefs.DeleteKey(m.PreferenceKey);PlayerPrefs.Save();log.AppendLine("ERRORS="+errors+"; four independent NWH-angle fixture, no hardware/human test");File.WriteAllText(SportsEvidencePaths.Folder("CabSteeringEvidence")+"/result.txt",log.ToString());Debug.Log("SPORTS_CAB_STEERING_PROBE_COMPLETE "+log);if(fixtureKeyboard!=null)UnityEngine.InputSystem.InputSystem.RemoveDevice(fixtureKeyboard);UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior=oldBackground;
 }
#endif
}
}
